import { r2CredentialsFromEnv, r2Service } from "./r2.service";
import { findReferencedImageKeys } from "./image-references";
import { logger } from "../logger/logger";

export const IMAGE_UPLOAD_GRACE_MS = 24 * 60 * 60 * 1000;
export const IMAGE_CLEANUP_INTERVAL_MS = 60 * 60 * 1000;

// Only files generated by this application; never installers or arbitrary bucket files.
export const isManagedImageKey = (key: string) =>
  /^(?:madrasas\/[a-z0-9-]+\/(?:students|teachers|staff|profile|branding|gallery|certificates|document-templates|misc)|platform\/(?:document-templates|website-demo))\/(?:\d{4}\/\d{2}\/)?[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.webp$/.test(
    key,
  );

let running = false;
const pending = new Set<string>();
let pendingTimer: NodeJS.Timeout | undefined;
let immediateRunning = false;

/** Immediate cleanup of detached images after successful business writes.
 * A failed operation is retried by the durable bucket sweep after the grace period.
 */
export function queueImageCleanup(keys: string[]) {
  for (const key of keys) if (isManagedImageKey(key)) pending.add(key);
  if (pendingTimer || immediateRunning || !pending.size) return;
  pendingTimer = setTimeout(() => {
    pendingTimer = undefined;
    const batch = [...pending];
    pending.clear();
    immediateRunning = true;
    void (async () => {
      const credentials = r2CredentialsFromEnv();
      if (!credentials) return;
      for (const key of batch) {
        if (!(await findReferencedImageKeys([key])).has(key)) {
          await r2Service.deleteObject(credentials, key);
        }
      }
    })()
      .catch((error) =>
        logger.error("[STORAGE:cleanup] immediate cleanup deferred to sweep", error),
      )
      .finally(() => {
        immediateRunning = false;
        queueImageCleanup([]);
      });
  }, 1500);
  pendingTimer.unref();
}

/** R2 itself is the durable retry inventory: failed deletes remain for the next sweep.
 * Newly uploaded drafts have 24 hours to be saved. Shared files, trashed rows and
 * historic template versions remain protected until their last reference is gone.
 */
export async function cleanupUnusedImages(now = Date.now()) {
  if (running) return;
  const credentials = r2CredentialsFromEnv();
  if (!credentials) return;
  running = true;
  let deleted = 0;
  let failed = 0;
  try {
    for (const prefix of ["madrasas/", "platform/"]) {
      let token: string | undefined;
      do {
        const page = await r2Service.listImages(credentials, prefix, token);
        const candidates = page.objects
          .filter(
            (object) =>
              object.Key &&
              isManagedImageKey(object.Key) &&
              object.LastModified &&
              object.LastModified.getTime() <= now - IMAGE_UPLOAD_GRACE_MS,
          )
          .map((object) => object.Key!);
        const referenced = await findReferencedImageKeys(candidates);
        for (const key of candidates) {
          if (referenced.has(key)) continue;
          // Recheck immediately before each delete so a save during the sweep
          // protects the file too. No deletion proceeds after a failed DB check.
          if ((await findReferencedImageKeys([key])).has(key)) continue;
          if (await r2Service.deleteObject(credentials, key)) deleted++;
          else failed++;
        }
        token = page.nextToken;
      } while (token);
    }
    logger.info("[STORAGE:cleanup] completed", { deleted, failed });
    return { deleted, failed };
  } finally {
    running = false;
  }
}

export function startImageCleanupScheduler() {
  const run = () => {
    void cleanupUnusedImages().catch((error) =>
      logger.error("[STORAGE:cleanup] retry on next sweep", error),
    );
  };
  const startup = setTimeout(run, 60_000);
  const interval = setInterval(run, IMAGE_CLEANUP_INTERVAL_MS);
  startup.unref();
  interval.unref();
}
